package com.optarena.app

object Stats {
    // Arithmetic mean as a Double.
    // BUG: sum and size are Int, so `sum / xs.size` truncates via integer
    // division before the .toDouble() widening.
    fun average(xs: List<Int>): Double {
        val sum = xs.sum()
        return (sum / xs.size).toDouble()
    }
}

