package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class StatsTest {

    @Test
    fun fractionalAverage() {
        assertEquals(2.5, Stats.average(listOf(1, 2, 3, 4)), 1e-9)
    }

    @Test
    fun repeatingAverage() {
        assertEquals(10.0 / 3.0, Stats.average(listOf(3, 3, 4)), 1e-9)
    }

    @Test
    fun wholeNumberAverage() {
        assertEquals(3.0, Stats.average(listOf(2, 4)), 1e-9)
    }

    @Test
    fun emptyIsZero() {
        assertEquals(0.0, Stats.average(emptyList()), 1e-9)
    }
}

